<?php
 defined('ABSPATH') || exit;
 $is_cart_page = function_exists('is_cart') && is_cart();
 $is_checkout_page = function_exists('is_checkout') && is_checkout();
 $is_account_page = function_exists('is_account_page') && is_account_page() && function_exists('tbv_staging_commerce_test_enabled') && tbv_staging_commerce_test_enabled();
 $is_commerce_page = $is_cart_page || $is_checkout_page || $is_account_page;
 $cart_count = function_exists('WC') && WC()->cart ? (int)WC()->cart->get_cart_contents_count() : 0;
 $cart_label = $cart_count > 0 ? sprintf('Cart (%d)', $cart_count) : 'Cart';
 $asset = trailingslashit(get_template_directory_uri()) . 'public/';
?><!doctype html><html <?php language_attributes(); ?>><head><meta charset="<?php bloginfo('charset'); ?>"><meta name="viewport" content="width=device-width, initial-scale=1"><?php wp_head(); ?><style>.tbv-native-cart-mobile{display:none}@media(max-width:1100px){.tbv-native-cart-mobile{display:inline-block;margin-left:auto;text-decoration:none;white-space:nowrap}.tbv-native-cart-mobile+.tbv-native-menu{margin-left:8px}}</style><?php if ($is_commerce_page): ?><link rel="stylesheet" href="<?php echo esc_url($asset . 'assets/native-cart.css'); ?>"><?php endif; ?><?php if ($is_checkout_page): ?><link rel="stylesheet" href="<?php echo esc_url($asset . 'assets/native-checkout.css'); ?>"><?php endif; ?><?php if ($is_account_page): ?><link rel="stylesheet" href="<?php echo esc_url(trailingslashit(get_template_directory_uri()) . 'account.css'); ?>"><?php endif; ?></head><body <?php body_class($is_commerce_page ? ($is_checkout_page ? 'tbv-native-cart tbv-native-checkout' : ($is_account_page ? 'tbv-native-cart tbv-native-account' : 'tbv-native-cart')) : ''); ?>><?php wp_body_open(); ?><?php if (!function_exists('tbv_staging_commerce_test_enabled') || !tbv_staging_commerce_test_enabled()): ?><p class="tbv-native-proof">WORDPRESS PREVIEW · No orders or payments</p><?php endif; ?>
<?php if ($is_commerce_page): ?>
<div class="tbv-native-banner"><span>FOR LABORATORY RESEARCH USE ONLY. NOT FOR HUMAN OR ANIMAL USE.</span><span> | </span><span>US WAREHOUSE FREE SHIPPING</span><span> | </span><span>FREE STANDARD SHIPPING $300+</span><span> | </span><span>FREE EXPRESS SHIPPING $550+</span></div>
<header class="tbv-native-header"><div class="tbv-native-header-inner"><a class="tbv-native-brand" href="<?php echo esc_url(home_url('/')); ?>"><img src="<?php echo esc_url($asset . 'images/header-vial-264.webp'); ?>" alt=""><span>10BottleValueCo</span></a><nav class="tbv-native-links" aria-label="Store navigation"><a href="<?php echo esc_url(home_url('/shop')); ?>">Shop (Worldwide)</a><a href="<?php echo esc_url(home_url('/us-warehouse')); ?>">Shop (US Warehouse)</a><a href="<?php echo esc_url(home_url('/shipping-prices')); ?>">Shipping Prices</a><a href="<?php echo esc_url(home_url('/faq')); ?>">FAQ</a><?php if (function_exists('tbv_staging_commerce_test_enabled') && tbv_staging_commerce_test_enabled()): ?><a href="<?php echo esc_url(wc_get_page_permalink('myaccount')); ?>"><?php echo is_user_logged_in() ? 'My account' : 'Log in'; ?></a><?php endif; ?><a class="tbv-native-cart-pill" href="<?php echo esc_url(wc_get_cart_url()); ?>"><?php echo esc_html($cart_label); ?></a></nav><a class="tbv-native-cart-pill tbv-native-cart-mobile" href="<?php echo esc_url(wc_get_cart_url()); ?>"><?php echo esc_html($cart_label); ?></a><details class="tbv-native-menu"><summary aria-label="Open menu">☰</summary><nav aria-label="Mobile store navigation"><a href="<?php echo esc_url(home_url('/')); ?>">Home</a><a href="<?php echo esc_url(home_url('/shop')); ?>">Shop (Worldwide)</a><a href="<?php echo esc_url(home_url('/us-warehouse')); ?>">Shop (US Warehouse)</a><a href="<?php echo esc_url(home_url('/shipping-prices')); ?>">Shipping Prices</a><a href="<?php echo esc_url(home_url('/faq')); ?>">FAQ</a><?php if (function_exists('tbv_staging_commerce_test_enabled') && tbv_staging_commerce_test_enabled()): ?><a href="<?php echo esc_url(wc_get_page_permalink('myaccount')); ?>"><?php echo is_user_logged_in() ? 'My account' : 'Log in'; ?></a><a href="<?php echo esc_url(wc_get_cart_url()); ?>">Cart</a><?php endif; ?></nav></details></div></header>
<main class="<?php echo $is_checkout_page ? 'tbv-native-checkout-main' : 'tbv-native-cart-main'; ?>"><h1><?php echo $is_account_page ? 'My account' : ($is_checkout_page ? 'Checkout' : 'Your cart'); ?></h1><?php while (have_posts()) { the_post(); the_content(); } ?></main>
<?php else: ?><main><?php if (function_exists('is_woocommerce') && is_woocommerce() && function_exists('woocommerce_content')) { woocommerce_content(); } else { while (have_posts()) { the_post(); the_title('<h1>', '</h1>'); the_content(); } } ?></main><?php endif; ?>
<?php wp_footer(); ?><?php if ($is_cart_page): ?><script defer src="<?php echo esc_url($asset . 'assets/native-cart.js'); ?>"></script><?php endif; ?></body></html>
